<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import {nodeConditionState} from '@/utils/kubernetesNode'
import {formatDateTime} from '@/utils/time'
import { useI18n } from 'vue-i18n'
import { formatKubeQuantity, podSpec, type KubeObject, type KubeType } from '@/api/kubernetes'
import { resourceCells, resourceColumns, ingressRoutes, podReferences, policyDirections, policyPeer, type KubeReference } from '@/utils/kubernetesPresentation'
import { kubeContainerDetails, kubeContainerProbes, kubeEnvironmentSources, kubeVolumeDetails } from '@/utils/kubernetesDetails'
import KubeResourceCell from './KubeResourceCell.vue'
const props=defineProps<{object:KubeObject;type:KubeType;canFollow:(reference?:KubeReference)=>boolean;container?:string;containerKey?:string;selectionIdentity?:string;section?:'all'|'containers'|'storage'|'scheduling'}>()
const emit=defineEmits<{follow:[reference:KubeReference];container:[name:string];containerKey:[key:string,identity?:string]}>()
const {t}=useI18n()
const cells=computed(()=>resourceCells(props.object,t))
const fields=computed(()=>resourceColumns(props.type,t).filter(item=>!['name','namespace','status','created','usage','images'].includes(item.key)))
const containers=computed(()=>kubeContainerDetails(props.object))
const containerGroups=computed(()=>(['app','init','ephemeral'] as const).map(kind=>({kind,items:containers.value.filter(item=>item.kind===kind)})).filter(group=>group.items.length))
const selectedContainerKey=ref('')
const selectedContainer=computed(()=>containers.value.find(item=>item.key===selectedContainerKey.value))
const containerMissing=computed(()=>Boolean(selectedContainerKey.value)&&!selectedContainer.value)
function initialContainerKey(){
  if(props.containerKey)return props.containerKey
  if(props.container)return containers.value.find(item=>item.container.name===props.container)?.key??`missing/${props.container}`
  return containers.value.find(item=>item.kind==='app')?.key??containers.value[0]?.key??''
}
function selectContainer(key:string,name?:string){
  const item=containers.value.find(container=>container.key===key)
  if(!item||name!==undefined&&item.container.name!==name)return
  selectedContainerKey.value=key
  if(props.object.kind==='Pod')emit('container',item.container.name)
}
function containerKeydown(event:KeyboardEvent){
  if(!['ArrowUp','ArrowDown','Home','End'].includes(event.key))return
  const items=containerGroups.value.flatMap(group=>group.items)
  if(!items.length)return
  const current=items.findIndex(item=>item.key===selectedContainerKey.value)
  const index=event.key==='Home'?0:event.key==='End'?items.length-1:current<0?(event.key==='ArrowUp'?items.length-1:0):event.key==='ArrowUp'?(current-1+items.length)%items.length:(current+1)%items.length
  event.preventDefault();selectContainer(items[index]!.key)
  const root=event.currentTarget as HTMLElement|null
  root?.querySelectorAll<HTMLButtonElement>('[data-container-key]')[index]?.focus()
}
watch(()=>`${props.selectionIdentity??''}/${props.object.kind}/${props.object.metadata?.uid??props.object.metadata?.name}`,()=>{selectedContainerKey.value=initialContainerKey()}, {immediate:true})
watch(()=>props.containerKey,key=>{if(key!==undefined)selectedContainerKey.value=key||initialContainerKey()},{flush:'sync'})
watch(()=>props.container,name=>{if(name!==undefined&&props.containerKey===undefined)selectedContainerKey.value=initialContainerKey()},{flush:'sync'})
watch(containers,()=>{if(!selectedContainerKey.value)selectedContainerKey.value=initialContainerKey()})
// 已保存的选择失效时保留原标识并提示，不能静默切到另一个容器。
watch(selectedContainerKey,key=>{if(key&&props.section&&props.section!=='all'&&containers.value.some(item=>item.key===key)){if(props.selectionIdentity)emit('containerKey',key,props.selectionIdentity);else emit('containerKey',key)}},{immediate:true})
const environment=computed(()=>kubeEnvironmentSources(selectedContainer.value?.container??{},props.object.metadata?.namespace))
const probes=computed(()=>kubeContainerProbes(selectedContainer.value?.container??{}))
const configuration=computed(()=>podSpec(props.object))
const volumes=computed(()=>kubeVolumeDetails(props.object))
const schedulingFields=computed(()=>[
  ['nodeName','nodeAndIP'],['serviceAccountName','serviceAccount'],['priorityClassName','priorityClass'],
  ['restartPolicy','restartPolicy'],['terminationGracePeriodSeconds','terminationGracePeriod'],['hostNetwork','hostNetwork'],['dnsPolicy','dnsPolicy'],
].filter(([key])=>configuration.value[key!]!==undefined&&configuration.value[key!]!=='').map(([key,label])=>({key:key!,label:label!,value:configuration.value[key!]})))
const schedulingRules=computed(()=>['affinity','tolerations','topologySpreadConstraints'].filter(key=>configuration.value[key]&&Object.keys(configuration.value[key]).length))
const references=computed(()=>podReferences(props.object))
const routes=computed(()=>ingressRoutes(props.object))
const policyRules=computed(()=>policyDirections(props.object).flatMap(direction=>(props.object.spec?.[direction.toLowerCase()]??[]).map((rule:KubeObject,index:number)=>({direction,index,peers:rule[direction==='Ingress'?'from':'to']??[],ports:rule.ports??[]}))))
const parameters=computed(()=>Object.entries(props.object.parameters??{}))
const source=computed(()=>{const spec=props.object.spec??{};if(spec.csi)return {label:'CSI',value:`${spec.csi.driver} / ${spec.csi.volumeHandle}`};if(spec.nfs)return {label:'NFS',value:`${spec.nfs.server}:${spec.nfs.path}`};if(spec.local)return {label:'Local',value:spec.local.path};if(spec.hostPath)return {label:'HostPath',value:spec.hostPath.path};return undefined})
const containerState=(runtime?:KubeObject)=>runtime?.state?.waiting?.reason??runtime?.state?.terminated?.reason??(runtime?.state?.running?t('k8s.containerRunning'):'—')
const booleanValue=(value:unknown)=>typeof value==='boolean'?t(value?'k8s.yes':'k8s.no'):'—'
const environmentSourceLabel=(kind:string)=>t(`k8s.${({direct:'directlyConfigured',field:'fieldReference',resource:'resourceReference',configmap:'type_configmaps',secret:'type_secrets'} as Record<string,string>)[kind]??'state_unknown'}`)
const volumeTypeLabel=(kind:string)=>['emptyDir','configMap','secret','persistentVolumeClaim'].includes(kind)?t(`k8s.volume_${kind}`):kind||'—'
const volumePropertyLabel=(key:string)=>t(`k8s.${({medium:'volumeMedium',sizeLimit:'sizeLimit',path:'path',type:'volumeType',driver:'volumeDriver',fsType:'fileSystem',readOnly:'readOnly',optional:'optionalReference',defaultMode:'fileMode'} as Record<string,string>)[key]}`)
const volumeProperties=(volume:KubeObject)=>['medium','sizeLimit','path','type','driver','fsType','readOnly','optional','defaultMode'].filter(key=>volume.source[key]!==undefined).map(key=>({key,value:key==='sizeLimit'?formatKubeQuantity('storage',volume.source[key]):typeof volume.source[key]==='boolean'?booleanValue(volume.source[key]):String(volume.source[key])}))
const resources=(container:KubeObject,field:string)=>Object.entries(container.resources?.[field]??{}).map(([key,value])=>`${key}: ${formatKubeQuantity(key,value)}`).join(' · ')||'—'
const rawResources=(container:KubeObject,field:string)=>Object.entries(container.resources?.[field]??{}).map(([key,value])=>`${key}: ${value}`).join(' · ')
</script>
<template>
  <section v-if="(!section||section==='all')&&fields.length" class="resource-detail-section kube-facts-section"><h4>{{ t('k8s.resourceSettings') }}</h4><dl class="kube-detail-facts"><div v-for="field in fields" :key="field.key"><dt>{{ field.label }}</dt><dd><KubeResourceCell :cell="cells[field.key]" :date="['jobTiming','lastSchedule'].includes(field.key)" :can-follow="canFollow(cells[field.key]?.reference)" @follow="emit('follow',$event)" /></dd></div></dl></section>

  <section v-if="(!section||section==='all'||section==='containers')&&(containers.length||containerMissing||section==='containers')" class="resource-detail-section kube-container-config">
    <div class="kube-container-layout">
      <nav class="kube-container-list" :aria-label="t('k8s.containers')" @keydown="containerKeydown">
        <section v-for="group in containerGroups" :key="group.kind" class="kube-container-group">
          <h4>{{ t(`k8s.containerKind_${group.kind}`) }} <span>{{ group.items.length }}</span></h4>
          <button v-for="item in group.items" :key="item.key" type="button" :data-container-key="item.key" class="kube-container-choice" :class="{'is-selected':selectedContainer?.key===item.key}" :aria-pressed="selectedContainer?.key===item.key" @click="selectContainer(item.key,item.container.name)">
            <strong>{{ item.container.name }}</strong><span v-if="item.container.restartPolicy==='Always'">{{ t('k8s.nativeSidecar') }}</span>
          </button>
        </section>
      </nav>
      <div class="kube-container-content">
        <a-alert v-if="containerMissing" type="warning" show-icon message="所选容器已不存在，请在左侧重新选择容器。" />
        <a-empty v-else-if="!selectedContainer" :description="t('k8s.emptyData')" />
        <div v-if="selectedContainer" :key="`${object.metadata.uid}/${selectedContainer.key}`" class="kube-container-summary">
      <header class="kube-container-heading"><h4>{{ selectedContainer.container.name }}</h4><a-tag>{{ t(`k8s.containerKind_${selectedContainer.kind}`) }}</a-tag></header>
      <dl class="kube-detail-facts">
        <div class="container-image"><dt>{{ t('k8s.image') }}</dt><dd><code>{{ selectedContainer.container.image||'—' }}</code></dd></div>
        <div :title="rawResources(selectedContainer.container,'requests')"><dt>{{ t('k8s.resourceRequests') }}</dt><dd>{{ resources(selectedContainer.container,'requests') }}</dd></div>
        <div :title="rawResources(selectedContainer.container,'limits')"><dt>{{ t('k8s.resourceLimits') }}</dt><dd>{{ resources(selectedContainer.container,'limits') }}</dd></div>
        <div v-if="object.kind==='Pod'"><dt>{{ t('k8s.status') }}</dt><dd>{{ containerState(selectedContainer.runtime) }}<div v-if="selectedContainer.runtime" class="muted">{{ t('k8s.restarts') }}: {{ selectedContainer.runtime.restartCount??'—' }}</div></dd></div>
        <div v-if="selectedContainer.container.imagePullPolicy"><dt>{{ t('k8s.imagePullPolicy') }}</dt><dd>{{ selectedContainer.container.imagePullPolicy }}</dd></div>
        <div v-if="selectedContainer.container.workingDir"><dt>{{ t('k8s.workingDir') }}</dt><dd><code>{{ selectedContainer.container.workingDir }}</code></dd></div>
        <div v-if="object.kind==='Pod'&&selectedContainer.runtime"><dt>{{ t('k8s.readyAndStarted') }}</dt><dd>{{ booleanValue(selectedContainer.runtime.ready) }} / {{ booleanValue(selectedContainer.runtime.started) }}</dd></div>
        <div v-if="selectedContainer.runtime?.state?.running?.startedAt"><dt>{{ t('k8s.containerStarted') }}</dt><dd>{{ formatDateTime(selectedContainer.runtime.state.running.startedAt) }}</dd></div>
        <div v-if="selectedContainer.runtime?.containerID"><dt>{{ t('k8s.containerID') }}</dt><dd><code>{{ selectedContainer.runtime.containerID }}</code></dd></div>
        <div v-if="selectedContainer.runtime?.imageID"><dt>{{ t('k8s.imageID') }}</dt><dd><code>{{ selectedContainer.runtime.imageID }}</code></dd></div>
        <div v-if="selectedContainer.runtime?.state?.waiting?.message"><dt>{{ t('k8s.containerWaiting') }}</dt><dd>{{ selectedContainer.runtime.state.waiting.message }}</dd></div>
        <div v-if="selectedContainer.runtime?.state?.terminated"><dt>{{ t('k8s.currentContainerInstance') }}</dt><dd>{{ selectedContainer.runtime.state.terminated.reason||'—' }} · {{ t('k8s.exitCode') }}: {{ selectedContainer.runtime.state.terminated.exitCode??'—' }}<div>{{ formatDateTime(selectedContainer.runtime.state.terminated.finishedAt) }}</div></dd></div>
        <div v-if="selectedContainer.runtime?.lastState?.terminated"><dt>{{ t('k8s.previousContainerInstance') }}</dt><dd>{{ selectedContainer.runtime.lastState.terminated.reason||'—' }} · {{ t('k8s.exitCode') }}: {{ selectedContainer.runtime.lastState.terminated.exitCode??'—' }}<div>{{ formatDateTime(selectedContainer.runtime.lastState.terminated.finishedAt) }}</div></dd></div>
      </dl>
      <template v-if="selectedContainer.container.command?.length||selectedContainer.container.args?.length"><h4>{{ t('k8s.startupAndEnv') }}</h4><dl class="kube-detail-facts"><div v-if="selectedContainer.container.command?.length"><dt>{{ t('k8s.commandLines') }}</dt><dd><code>{{ selectedContainer.container.command.join(' ') }}</code></dd></div><div v-if="selectedContainer.container.args?.length"><dt>{{ t('k8s.argumentLines') }}</dt><dd><code>{{ selectedContainer.container.args.join(' ') }}</code></dd></div></dl></template>
      <template v-if="selectedContainer.container.ports?.length"><h4>{{ t('k8s.ports') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.name') }}</th><th>{{ t('k8s.protocol') }}</th><th>{{ t('k8s.ports') }}</th><th>{{ t('k8s.hostPort') }}</th></tr></thead><tbody><tr v-for="(port,index) in selectedContainer.container.ports" :key="index"><td>{{ port.name||'—' }}</td><td>{{ port.protocol??'TCP' }}</td><td>{{ port.containerPort??'—' }}</td><td>{{ port.hostPort!==undefined?`${port.hostIP?`${port.hostIP}:`:''}${port.hostPort}`:'—' }}</td></tr></tbody></table></div></template>
      <template v-if="environment.length"><h4>{{ t('k8s.env') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.name') }}</th><th>{{ t('k8s.environmentSource') }}</th><th>{{ t('k8s.referenceName') }}</th></tr></thead><tbody><tr v-for="(env,index) in environment" :key="index"><td><code>{{ env.name }}</code><div v-if="env.prefix" class="muted">{{ t('k8s.environmentPrefix') }}: {{ env.prefix }}</div></td><td>{{ environmentSourceLabel(env.kind) }}<div v-if="env.optional!==undefined" class="muted">{{ t('k8s.optionalReference') }}: {{ booleanValue(env.optional) }}</div></td><td><template v-if="env.reference"><button v-if="canFollow(env.reference)" class="detail-link" @click="emit('follow',env.reference)">{{ env.reference.name }}</button><span v-else>{{ env.reference.name }}</span><span v-if="env.key"> / {{ env.key }}</span></template><code v-else>{{ env.field||'—' }}</code></td></tr></tbody></table></div></template>
      <template v-if="probes.length"><h4>{{ t('k8s.healthProbes') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.probeKind') }}</th><th>{{ t('k8s.referenceName') }}</th><th>{{ t('k8s.resourceSettings') }}</th></tr></thead><tbody><tr v-for="probe in probes" :key="probe.key"><td>{{ t(`k8s.${probe.key}`) }}<div v-if="probe.method" class="muted">{{ t(`k8s.probe_${probe.method}`) }}</div></td><td><code>{{ probe.target||'—' }}</code></td><td><div v-for="timing in probe.timings" :key="timing.key">{{ t(`k8s.${timing.key}`) }}: {{ timing.value }}</div></td></tr></tbody></table></div></template>
      <template v-if="selectedContainer.container.volumeMounts?.length"><h4>{{ t('k8s.volumeMounts') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.volumeName') }}</th><th>{{ t('k8s.mountPath') }}</th><th>{{ t('k8s.subPath') }}</th><th>{{ t('k8s.readOnly') }}</th></tr></thead><tbody><tr v-for="mount in selectedContainer.container.volumeMounts" :key="`${mount.name}/${mount.mountPath}`"><td>{{ mount.name }}</td><td><code>{{ mount.mountPath }}</code></td><td>{{ mount.subPath??mount.subPathExpr??'—' }}</td><td>{{ booleanValue(mount.readOnly) }}</td></tr></tbody></table></div></template>
        </div>
      </div>
    </div>
  </section>

  <section v-if="(!section||section==='all'||section==='scheduling')&&containers.length&&(schedulingFields.length||Object.keys(configuration.nodeSelector??{}).length||schedulingRules.length)" class="resource-detail-section"><h4>{{ t('k8s.scheduling') }}</h4><dl class="kube-detail-facts"><div v-for="field in schedulingFields" :key="field.key"><dt>{{ t(`k8s.${field.label}`) }}</dt><dd><button v-if="field.key==='nodeName'&&canFollow({resource:'nodes',name:field.value})" class="detail-link" @click="emit('follow',{resource:'nodes',name:field.value})">{{ field.value }}</button><span v-else>{{ typeof field.value==='boolean'?booleanValue(field.value):field.value }}</span></dd></div><div v-if="Object.keys(configuration.nodeSelector??{}).length"><dt>{{ t('k8s.nodeSelector') }}</dt><dd><div v-for="(value,key) in configuration.nodeSelector" :key="key"><code>{{ key }}={{ value }}</code></div></dd></div></dl><details v-for="key in schedulingRules" :key="key" class="kube-scheduling-rule"><summary>{{ t(`k8s.${key==='topologySpreadConstraints'?'topologySpread':key}`) }}</summary><pre class="kube-detail-code">{{ JSON.stringify(configuration[key],null,2) }}</pre></details></section>

  <section v-if="(!section||section==='all'||section==='storage')&&volumes.length" class="resource-detail-section"><h4>{{ t('k8s.volumes') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.volumeName') }}</th><th>{{ t('k8s.volumeType') }}</th><th>{{ t('k8s.referenceName') }}</th><th>{{ t('k8s.resourceSettings') }}</th></tr></thead><tbody><tr v-for="volume in volumes" :key="volume.name"><td>{{ volume.name }}</td><td>{{ volumeTypeLabel(volume.kind) }}</td><td><div v-for="reference in volume.references" :key="`${reference.resource}/${reference.name}`"><button v-if="canFollow(reference)" class="detail-link" @click="emit('follow',reference)">{{ reference.name }}</button><span v-else>{{ reference.name }}</span></div><span v-if="!volume.references.length">—</span></td><td><div v-for="property in volumeProperties(volume)" :key="property.key"><span class="muted">{{ volumePropertyLabel(property.key) }}: </span>{{ property.value }}</div></td></tr></tbody></table></div></section>

  <section v-if="(!section||section==='all')&&references.length" class="resource-detail-section"><h4>{{ t('k8s.referencedResources') }}</h4><div class="reference-list"><div v-for="reference in references" :key="`${reference.resource}/${reference.name}`"><span class="muted">{{ t(`k8s.type_${reference.resource}`) }}</span><button v-if="canFollow(reference)" class="detail-link" @click="emit('follow',reference)">{{ reference.name }}</button><span v-else>{{ reference.name }}</span></div></div></section>

  <a-empty v-if="section==='storage'&&!volumes.length" :description="t('k8s.workloadNoVolumes')" />
  <a-empty v-if="section==='scheduling'&&!schedulingFields.length&&!Object.keys(configuration.nodeSelector??{}).length&&!schedulingRules.length" :description="t('k8s.workloadNoScheduling')" />

  <section v-if="object.kind==='Service'" class="resource-detail-section"><h4>{{ t('k8s.portMapping') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.name') }}</th><th>{{ t('k8s.protocol') }}</th><th>{{ t('k8s.servicePort') }}</th><th>{{ t('k8s.targetPort') }}</th><th>NodePort</th></tr></thead><tbody><tr v-for="port in object.spec?.ports??[]" :key="`${port.port}/${port.protocol}`"><td>{{ port.name||'—' }}</td><td>{{ port.protocol??'TCP' }}</td><td>{{ port.port }}</td><td>{{ port.targetPort??port.port }}</td><td>{{ port.nodePort??'—' }}</td></tr></tbody></table></div><dl class="kube-detail-facts additional-facts"><div><dt>{{ t('k8s.sessionAffinity') }}</dt><dd>{{ object.spec?.sessionAffinity??'None' }}</dd></div><div><dt>{{ t('k8s.externalTrafficPolicy') }}</dt><dd>{{ object.spec?.externalTrafficPolicy??'—' }}</dd></div><div><dt>{{ t('k8s.publishNotReady') }}</dt><dd>{{ t(object.spec?.publishNotReadyAddresses?'k8s.yes':'k8s.no') }}</dd></div></dl><p class="detail-hint">{{ t('k8s.serviceReachabilityHint') }}</p></section>

  <section v-if="object.kind==='Ingress'" class="resource-detail-section"><h4>{{ t('k8s.routes') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.hostname') }}</th><th>{{ t('k8s.path') }}</th><th>{{ t('k8s.pathType') }}</th><th>{{ t('k8s.backend') }}</th><th>{{ t('k8s.servicePort') }}</th></tr></thead><tbody><tr v-for="(route,index) in routes" :key="index"><td>{{ route.host }}</td><td>{{ route.path }}</td><td>{{ route.pathType }}</td><td><button v-if="route.service&&canFollow({resource:'services',name:route.service,namespace:object.metadata.namespace})" class="detail-link" @click="emit('follow',{resource:'services',name:route.service!,namespace:object.metadata.namespace})">{{ route.service }}</button><span v-else>{{ route.service??route.resource??'—' }}</span></td><td>{{ route.port??'—' }}</td></tr></tbody></table></div><a-empty v-if="!routes.length" :description="t('k8s.emptyData')" /><div v-if="object.spec?.tls?.length" class="tls-list"><div v-for="(tls,index) in object.spec.tls" :key="index"><span>{{ (tls.hosts??[]).join(', ')||'*' }}</span><span class="muted">Secret</span><button v-if="tls.secretName&&canFollow({resource:'secrets',name:tls.secretName,namespace:object.metadata.namespace})" class="detail-link" @click="emit('follow',{resource:'secrets',name:tls.secretName,namespace:object.metadata.namespace})">{{ tls.secretName }}</button><span v-else>{{ tls.secretName||'—' }}</span></div></div><p class="detail-hint">{{ t('k8s.ingressReachabilityHint') }}</p></section>

  <section v-if="object.kind==='NetworkPolicy'" class="resource-detail-section"><h4>{{ t('k8s.policyRules') }}</h4><p class="detail-hint">{{ t('k8s.policyRulesHint') }}</p><a-empty v-if="!policyRules.length" :description="t('k8s.denySelectedDirections')" /><div v-else class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.policyDirection') }}</th><th>{{ t('k8s.sourceOrDestination') }}</th><th>{{ t('k8s.allowedPorts') }}</th></tr></thead><tbody><tr v-for="rule in policyRules" :key="`${rule.direction}/${rule.index}`"><td>{{ t(rule.direction==='Ingress'?'k8s.ingressTraffic':'k8s.egressTraffic') }} #{{ rule.index+1 }}</td><td><div v-for="(peer,index) in rule.peers" :key="index">{{ policyPeer(peer,t) }}</div><span v-if="!rule.peers.length">{{ t('k8s.allTraffic') }}</span></td><td>{{ rule.ports.length?rule.ports.map((port:KubeObject)=>`${port.port??'*'}${port.endPort?`–${port.endPort}`:''}/${port.protocol??'TCP'}`).join(' · '):t('k8s.allPorts') }}</td></tr></tbody></table></div></section>

  <section v-if="object.kind==='PersistentVolume'||object.kind==='StorageClass'" class="resource-detail-section"><h4>{{ t('k8s.storageSettings') }}</h4><dl class="kube-detail-facts"><div v-if="source"><dt>{{ source.label }}</dt><dd>{{ source.value }}</dd></div><div><dt>{{ t('k8s.mountOptions') }}</dt><dd>{{ (object.mountOptions??object.spec?.mountOptions??[]).join(', ')||'—' }}</dd></div><div v-for="[key,value] in parameters" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></div></dl></section>

  <section v-if="(!section||section==='all')&&object.status?.conditions?.length" class="resource-detail-section"><h4>{{ t('k8s.conditions') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.conditionType') }}</th><th>{{ t('k8s.status') }}</th><th>{{ t('k8s.reason') }}</th><th>{{ t('k8s.message') }}</th><th>{{ t('k8s.nodeHeartbeat') }}</th><th>{{ t('k8s.nodeTransition') }}</th></tr></thead><tbody><tr v-for="condition in object.status.conditions" :key="condition.type"><td>{{ condition.type }}</td><td><a-tag :color="object.kind==='Node'?nodeConditionState(condition):'default'">{{ condition.status }}</a-tag></td><td>{{ condition.reason||'—' }}</td><td>{{ condition.message||'—' }}</td><td>{{ formatDateTime(condition.lastHeartbeatTime) }}</td><td>{{ formatDateTime(condition.lastTransitionTime) }}</td></tr></tbody></table></div></section>
</template>
<style scoped>
